    "id": "semana17_ped_q031",
    "text": "¿Cuál es la principal vía de transmisión del sarampión?",
    "options": [
      "Fecal-oral mediante alimentos contaminados",
      "Contacto directo con lesiones cutáneas",
      "Respiratoria mediante aerosoles de pequeñas gotas",
      "Transplacentaria durante la infección materna",
      "Vectorial mediante artrópodos"
    ],
    "correctOptionIndex": 2,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nEl virus del sarampión ingresa a través del tracto respiratorio o la conjuntiva y se transmite principalmente mediante aerosoles de pequeñas gotas suspendidos en el aire. Su elevada transmisibilidad permite que el virus permanezca suspendido durante un tiempo prolongado.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Puerta de entrada: tracto respiratorio o conjuntiva.\r\n- Transmisión: aerosoles de pequeñas gotas.\r\n- El contacto cara a cara no es indispensable para la transmisión.\r\n- El virus puede permanecer suspendido en el aire hasta 2 horas después de que la persona infectada abandona el lugar.\r\n- El período de incubación suele ser de 8-12 días.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Sarampión = transmisión respiratoria extremadamente eficiente.Perla CONAREM: una persona susceptible puede infectarse incluso después de que el enfermo haya abandonado el ambiente.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 293, pág. 1958.",
