    "id": "semana17_ped_q032",
    "text": "Un niño presenta fiebre elevada, tos, coriza, conjuntivitis y posteriormente desarrolla un exantema prominente. ¿Cuál es el diagnóstico más probable?",
    "options": [
      "Sarampión",
      "Escarlatina",
      "Eritema infeccioso",
      "Exantema súbito",
      "Enfermedad de Kawasaki"
    ],
    "correctOptionIndex": 0,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nEl sarampión se caracteriza por fiebre alta, tos, coriza, conjuntivitis y exantema prominente. La combinación de síntomas respiratorios y conjuntivales que preceden al exantema constituye una presentación clínica característica.\r\n\r\n🔑 CONCEPTOS CLAVEEl curso clínico presenta cuatro fases:\r\n\r\n- Incubación.\r\n- Pródromos.\r\n- Exantema.\r\n- Recuperación.\r\n- Durante la incubación, el paciente permanece asintomático. El período prodrómico se caracteriza por fiebre y síntomas respiratorios antes de la aparición del exantema.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Sarampión → fiebre + tos + coriza + conjuntivitis + exantema.\r\n- La clave es reconocer el pródromo respiratorio antes del exantema.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 293, págs. 1958-1959.",
