    "correctOptionIndex": 2,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLa otitis media es la complicación más frecuente del sarampión. Su incidencia fue elevada durante las epidemias y puede acompañarse de infección bacteriana secundaria.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Otitis media: complicación más frecuente.\r\n- Neumonía: causa más frecuente de muerte por sarampión.\r\n- La neumonía puede ser causada directamente por el virus o por sobreinfección bacteriana.\r\n- Entre los patógenos bacterianos descritos se encuentran Streptococcus pneumoniae, Haemophilus influenzae y Staphylococcus aureus.\r\n- La diarrea y los vómitos también son complicaciones frecuentes.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Más frecuente → otitis media.Principal causa de muerte → neumonía.\r\n- Esta diferencia es una trampa clásica de examen.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 293, pág. 1961.",
