    "correctOptionIndex": 4,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nEl tratamiento del sarampión es fundamentalmente de soporte, ya que no existe un tratamiento antiviral específico aprobado de uso rutinario. Las medidas principales incluyen hidratación, oxigenación y confort.\r\n\r\n🔑 CONCEPTOS CLAVETratamiento:\r\n\r\n- Hidratación.\r\n- Oxigenación cuando sea necesaria.\r\n- Medidas de confort.\r\n- Antipiréticos para controlar la fiebre.\r\n- Humidificación de la vía aérea y oxígeno suplementario si existe compromiso respiratorio.\r\n- La neumonía bacteriana secundaria requiere antibióticos.\r\n- La ribavirina posee actividad in vitro y puede considerarse en determinados pacientes inmunocomprometidos, pero no constituye el tratamiento rutinario.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Sarampión no complicado → soporte, no antiviral rutinario.\r\n- Antibiótico únicamente ante infección bacteriana secundaria, no para tratar el virus.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 293, pág. 1962.",
