    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLa vitamina A reduce la morbimortalidad asociada al sarampión y debe administrarse durante 2 días consecutivos. La dosis depende de la edad.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n**Vitamina A en sarampión:**\r\n- ≥12 meses: 200.000 UI/día.\r\n- 6-11 meses: 100.000 UI/día.\r\n- <6 meses: 50.000 UI/día.\r\n- Administrar durante 2 días consecutivos.\r\n- En niños con signos y síntomas de deficiencia de vitamina A puede administrarse una tercera dosis apropiada para la edad 2-4 semanas después de la segunda.\r\n\r\n⚡ REPASO ACTIVORegla rápida por edad:\r\n\r\n- <6 meses → 50.000 UI6-11 meses → 100.000 UI≥12 meses → 200.000 UI\r\n- Siempre durante 2 días consecutivos.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 293, pág. 1962.",
