    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLa vacunación administrada dentro de las 72 horas posteriores a la exposición puede prevenir el sarampión o modificar su evolución en personas susceptibles.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n**Profilaxis posexposición:**\r\n- Vacuna: dentro de las primeras 72 horas.\r\n- Inmunoglobulina: puede administrarse hasta 6 días después de la exposición.\r\n\r\n**Inmunoglobulina:**\r\n- Inmunocompetente: 0,5 mL/kg IM, máximo 15 mL.\r\n- Inmunocomprometido: 400 mg/kg IV.\r\n\r\n**La inmunoglobulina está indicada especialmente en:**\r\n- Lactantes <6 meses.\r\n- Embarazadas.\r\n- Personas inmunocomprometidas susceptibles.\r\n\r\n⚡ REPASO ACTIVORegla CONAREM:\r\n\r\n- Vacuna → 72 horas.Inmunoglobulina → hasta 6 días.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 293, págs. 1963-1964.",
