    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLa glomerulonefritis aguda no forma parte de las complicaciones descritas del sarampión. Entre las complicaciones relevantes se encuentran la otitis media, neumonía, encefalitis y panencefalitis esclerosante subaguda.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Otitis media: complicación más frecuente.\r\n- Neumonía: causa más frecuente de muerte.\r\n- Encefalitis: ocurre aproximadamente en 1-3 por cada 1.000 casos.\r\n- Diarrea y vómitos: frecuentes, especialmente en niños pequeños.\r\n- Convulsiones febriles: ocurren en <3%.\r\n- Encefalitis postinfecciosa: puede dejar secuelas neurológicas.\r\n- Panencefalitis esclerosante subaguda (PEES): complicación neurológica crónica y progresiva.\r\n- También pueden presentarse queratoconjuntivitis, laringotraqueítis, miocarditis y complicaciones bacterianas secundarias.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n**En preguntas EXCEPTO, identifica primero las complicaciones clásicas:**\r\n- Otitis → más frecuente.Neumonía → principal causa de muerte.Encefalitis → 1-3/1.000.PEES → tardía, progresiva y grave.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 293, págs. 1961-1962.",
