    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLa linfadenopatía retroauricular, suboccipital y cervical posterior constituye uno de los hallazgos clínicos más prominentes de la rubéola. En niños puede ser la primera manifestación de la enfermedad.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- La infección posnatal suele ser una enfermedad leve.\r\n- Período de incubación: 16-18 días.\r\n- Pródromo en niños: habitualmente ausente o leve.\r\n\r\n**Puede presentar:**\r\n- Fiebre baja.\r\n- Dolor de garganta.\r\n- Ojos rojos.\r\n- Cefalea.\r\n- Malestar.\r\n- Anorexia.\r\n- Linfadenopatía.\r\n- Adenopatías características: suboccipitales, retroauriculares y cervicales posteriores.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Rubéola + adenopatías retroauriculares/suboccipitales = asociación clásica.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 294, págs. 1965-1966.",
