    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLa trombocitopenia posinfecciosa es la complicación más frecuente de la rubéola posnatal. Se presenta aproximadamente en 1 de cada 3.000 casos y ocurre con mayor frecuencia en niños y niñas.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Trombocitopenia posinfecciosa: aproximadamente 1/3.000 casos.\r\n- Suele aparecer alrededor de 2 semanas después del inicio del exantema.\r\n\r\n**Puede manifestarse con:**\r\n- Petequias.\r\n- Epistaxis.\r\n- Sangrado gastrointestinal.\r\n- Hematuria.\r\n- Habitualmente es autolimitada.\r\n- La artritis posterior a rubéola es más frecuente en adultos, especialmente mujeres.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Rubéola + complicación más frecuente → trombocitopenia posinfecciosa.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 294, pág. 1967.",
