    "explanation": "🧠 ¿POR QUÉ ES LA CORRECTA?\r\n\r\nLa afectación parotídea es bilateral en aproximadamente el 70% de los casos y permanece unilateral en alrededor del 30%. Cuando ambas parótidas están comprometidas, la inflamación no tiene que aparecer simultáneamente; una glándula puede afectarse antes que la otra. La parótida comprometida suele ser dolorosa y sensible, el dolor puede aumentar con líquidos ácidos y la tumefacción puede producir borramiento del ángulo mandibular y desplazamiento del lóbulo auricular hacia arriba y afuera.\r\n\r\n📚 CONCEPTOS CLAVE\r\n\r\n- Bilateral: ≈70%.\r\n- Unilateral: ≈30%.\r\n- El compromiso bilateral puede ser secuencial.\r\n- Parótida dolorosa y sensible.\r\n- El dolor aumenta con líquidos ácidos.\r\n- Puede borrarse el ángulo mandibular.\r\n- El lóbulo auricular puede desplazarse hacia arriba y afuera.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- 70% bilateral / 30% unilateral, pero bilateral no significa simultánea.\r\n- Esa última diferencia es la trampa de examen.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 295, pág. 1970.",
