    "correctOptionIndex": 2,
    "explanation": "🧠 ¿POR QUÉ ES LA CORRECTA?\r\n\r\nLas infecciones por parvovirus B19 son frecuentes en todo el mundo. Las formas clínicamente aparentes, como el eritema infeccioso, se presentan principalmente en niños en edad escolar: aproximadamente 70% de los casos ocurren entre los 5 y 15 años.\r\n\r\n📚 CONCEPTOS CLAVE\r\n\r\n- La infección por parvovirus B19 tiene distribución mundial.\r\n- La mayoría de los casos clínicamente aparentes ocurren entre 5–15 años.\r\n- Presenta picos estacionales a finales del invierno y primavera.\r\n- También pueden presentarse infecciones esporádicas durante todo el año.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- Parvovirus B19 + niño escolar + exantema = eritema infeccioso.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 298, pág. 1987.",
