    "text": "¿Cuál es la principal célula diana del parvovirus B19?",
    "options": [
      "Linfocito B maduro",
      "Neutrófilo circulante",
      "Hepatocito",
      "Precursor eritroide",
      "Célula epitelial respiratoria"
    ],
    "correctOptionIndex": 3,
    "explanation": "🧠 ¿POR QUÉ ES LA CORRECTA?\r\n\r\nEl parvovirus B19 presenta un marcado tropismo por la línea celular eritroide, especialmente por los precursores eritroides cercanos al estadio pronormoblasto. La infección produce lisis celular y una depleción transitoria de los precursores eritroides, provocando una interrupción temporal de la eritropoyesis.\r\n\r\n📚 CONCEPTOS CLAVE\r\n\r\n- Diana principal → precursores eritroides.\r\n- La infección provoca lisis celular.\r\n- Produce detención transitoria de la eritropoyesis.\r\n- El tropismo eritroide se relaciona con el antígeno P del grupo sanguíneo.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- B19 → línea eritroide → frena transitoriamente la producción de eritrocitos.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 298, págs. 1987–1988.",
