    "explanation": "🧠 ¿POR QUÉ ES LA CORRECTA?\r\n\r\nEl eritema infeccioso presenta un período de incubación de 4–28 días, con un promedio de 16–17 días. Posteriormente puede aparecer un pródromo leve y, finalmente, el exantema característico.\r\n\r\n📚 CONCEPTOS CLAVE\r\n\r\n- Incubación: 4–28 días.\r\n- Promedio: 16–17 días.\r\n- El pródromo suele ser leve.\r\n- El exantema característico incluye las “mejillas abofeteadas” y posteriormente un patrón reticulado.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- Parvovirus B19 → incubación amplia: 4–28 días → promedio 16–17 días.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 298, pág. 1988.",
