    "explanation": "🧠 ¿POR QUÉ ES LA CORRECTA?\r\n\r\nLa infección materna primaria por parvovirus B19 se asocia principalmente con hidropesía fetal no inmunitaria y muerte fetal intrauterina. El virus produce aplasia de la serie eritroide fetal durante una etapa de rápida expansión de la masa eritrocitaria. Esto puede generar anemia profunda, insuficiencia cardíaca de alto gasto y finalmente hidropesía fetal.\r\n\r\n📚 CONCEPTOS CLAVE\r\n\r\n- Infección materna primaria → riesgo de hidropesía fetal no inmunitaria.\r\n- Riesgo estimado de hidropesía fetal: 2–5%.\r\n- Mecanismo: aplasia eritroide fetal.\r\n- Consecuencia: anemia profunda → insuficiencia cardíaca de alto gasto → hidropesía.\r\n- Puede producirse pérdida fetal en cualquier etapa de la gestación.\r\n- La mayoría de los fetos infectados intraútero nacen normales a término.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- Parvovirus B19 en embarazo → anemia fetal → alto gasto cardíaco → hidropesía fetal no inmunitaria.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 298, pág. 1989.",
