    "explanation": "🧠 ¿POR QUÉ ES LA CORRECTA?\r\n\r\nEl síndrome papular-purpúrico de guantes y calcetines es una manifestación cutánea característica asociada al parvovirus B19. Presenta fiebre, prurito, edema doloroso y eritema localizado en las extremidades distales, adoptando una distribución característica en guantes y calcetines. Posteriormente pueden aparecer petequias acrales y lesiones orales. Generalmente es autolimitado.\r\n\r\n📚 CONCEPTOS CLAVE\r\n\r\n- Distribución: manos y pies en patrón de guantes y calcetines.\r\n- Puede presentar fiebre.\r\n- Puede producir prurito.\r\n- Existe edema doloroso y eritema distal.\r\n- Posteriormente aparecen petequias acrales.\r\n- Puede acompañarse de lesiones orales.\r\n- Es autolimitado y suele resolverse en pocas semanas.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n**No confundir los dos patrones cutáneos:**\r\n- Eritema infeccioso → “mejillas abofeteadas” + exantema reticulado.Síndrome guantes-calcetines → eritema/edema distal + petequias/púrpura acral.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 298, págs. 1989–1990.",
