    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLa infección genital primaria sintomática puede estar precedida por un período corto de ardor y sensibilidad local. El período de incubación es de 2 a 7 días.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- La infección genital por VHS es frecuente en adolescentes y adultos jóvenes.\r\n- Puede adquirirse por transmisión genital-genital u oral-genital.\r\n- Tanto las personas sintomáticas como las asintomáticas pueden eliminar virus y transmitir la infección.\r\n- Las lesiones pueden aparecer en genitales externos, región perianal, glúteos y muslos.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Infección genital primaria: incubación de 2-7 días → ardor y sensibilidad local → vesículas sobre base eritematosa → pústulas → úlceras dolorosas → formación de costras.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- Herpes genital primario = incubación de 2-7 días.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 299, Herpes Simplex Virus.",
