    "correctOptionIndex": 0,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLas recurrencias de la infección ocular por VHS pueden provocar cicatrización corneal progresiva y lesión que conduce a ceguera. El compromiso ocular puede afectar conjuntiva, córnea o retina.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- La infección ocular puede ser primaria o recurrente.\r\n- La conjuntivitis o queratoconjuntivitis suele ser unilateral.\r\n- Puede asociarse con blefaritis y adenopatía preauricular dolorosa.\r\n- Las lesiones vesiculares pueden aparecer en la piel y en los márgenes palpebrales.\r\n- La recurrencia puede ocasionar lesión corneal progresiva.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Compromiso ocular por VHS: conjuntiva, córnea o retina. Puede producir conjuntivitis/queratoconjuntivitis, blefaritis, adenopatía preauricular dolorosa, edema corneal, cicatrización y erosiones corneales. Las recurrencias pueden culminar en cicatrización corneal progresiva y ceguera.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- VHS ocular recurrente → cicatriz corneal → riesgo de ceguera.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 299, Herpes Simplex Virus.",
