    "correctOptionIndex": 3,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nEl herpes labial o herpes febril constituye la manifestación más frecuente de la infección recurrente por VHS-1. Su localización más habitual es el borde bermellón del labio.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- El sitio más frecuente es el borde bermellón del labio.\r\n- También puede aparecer en nariz, mentón, mejillas y mucosa oral.\r\n- El pródromo puede incluir ardor, hormigueo, prurito o dolor.\r\n- Las vesículas aparecen pocas horas después del pródromo.\r\n- Las lesiones evolucionan posteriormente hacia pústulas, ulceración superficial y costras.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Evolución típica: pródromo de 3-6 horas → vesículas → pústulas → ulceración superficial → costras → reepitelización, habitualmente en 6-10 días.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- VHS-1 recurrente + borde bermellón = herpes labial.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 299, Herpes Simplex Virus.",
