    "correctOptionIndex": 2,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLa combinación de niño pequeño, fiebre, irritabilidad, rechazo de alimentos, gingivitis intensa y múltiples lesiones vesiculoulcerosas distribuidas por la cavidad oral es característica de la gingivoestomatitis herpética.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Afecta con mayor frecuencia a niños de 6 meses a 5 años.\r\n- Puede comenzar con fiebre, irritabilidad, disminución de la ingesta y rechazo a comer o beber.\r\n- Las encías están marcadamente inflamadas.\r\n- Las vesículas pueden distribuirse ampliamente por toda la cavidad oral.\r\n- Puede existir linfadenopatía submandibular dolorosa.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Localizaciones: encías, labios, lengua, paladar, amígdalas, faringe y piel perioral. Sin tratamiento, suele resolverse en 7-14 días; puede persistir linfadenopatía durante varias semanas.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- 6 meses-5 años + fiebre + gingivitis + múltiples úlceras orales = gingivoestomatitis herpética.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 299, Herpes Simplex Virus.",
