    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLa encefalitis por VHS es una infección necrosante aguda que generalmente compromete los lóbulos frontal y/o temporal. Puede manifestarse con fiebre, cefalea, vómitos, convulsiones, alteración de conciencia y manifestaciones neurológicas focales.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Es una causa importante de encefalitis esporádica no epidémica.\r\n- Casi siempre es causada por VHS-1.\r\n- Predomina en lóbulos frontal y/o temporal.\r\n- Puede producir anosmia, pérdida de memoria, conducta peculiar y afasia expresiva.\r\n- La mortalidad puede alcanzar 75% sin tratamiento.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Manifestaciones: fiebre, cefalea, rigidez de nuca, vómitos, convulsiones generalizadas, alteración de conciencia, anosmia, pérdida de memoria, cambios conductuales, afasia expresiva y otros signos focales.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- Encefalitis + alteración conductual/focalidad + frontal-temporal → VHS-1.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 299, Herpes Simplex Virus.",
