    "id": "semana17_ped_q080",
    "text": "Un niño presenta fiebre y exantema pruriginoso de predominio en tronco. En el examen se observan simultáneamente máculas, pápulas, vesículas y lesiones costrosas. ¿Cuál es el diagnóstico más probable?",
