    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLa coexistencia de lesiones cutáneas en diferentes etapas de evolución, junto con una distribución predominantemente centrípeta y prurito, es característica de la varicela.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- El exantema suele ser pruriginoso.\r\n- Predomina en tronco y regiones proximales.\r\n- Pueden aparecer nuevas lesiones durante varios días.\r\n- Las lesiones evolucionan desde máculas hasta vesículas y costras.\r\n- La presencia simultánea de diferentes estadios es un dato característico.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- En niños sanos pueden existir aproximadamente 300 lesiones, aunque el número puede variar desde menos de 10 hasta más de 1.500.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- Máculas + pápulas + vesículas + costras al mismo tiempo = varicela.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 300, Varicella-",
