    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLas infecciones bacterianas secundarias de la piel, generalmente producidas por estreptococos del grupo A o Staphylococcus aureus, son una complicación importante y frecuente de la varicela pediátrica.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Las infecciones secundarias de piel suelen deberse a estreptococos del grupo A o S. aureus.\r\n- Pueden variar desde impétigo hasta celulitis y linfadenitis.\r\n- También pueden producir abscesos subcutáneos.\r\n- Las infecciones invasivas pueden incluir sepsis, neumonía, artritis, osteomielitis y fascitis necrosante.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Manifestaciones bacterianas mencionadas: impétigo, celulitis, linfadenitis, abscesos subcutáneos, sepsis, neumonía, artritis, osteomielitis y fascitis necrosante.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- En un niño con varicela que presenta recurrencia de fiebre 3-4 días después del exantema, pensar en sobreinfección bacteriana secundaria.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 300, Varicella-",
