    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLa obstrucción de la vía aérea secundaria a edema del tejido linfático orofaríngeo ocurre en menos del 5% de los casos.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Linfadenopatía: aproximadamente 90%.\r\n- Esplenomegalia: aproximadamente 50%.\r\n- Hepatomegalia: aproximadamente 10%.\r\n- Obstrucción de vía aérea: <5%.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Hallazgos del examen físico: linfadenopatía generalizada 90% → esplenomegalia 50% → hepatomegalia 10%. La obstrucción de la vía aérea es una complicación menos frecuente.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- Número de examen: obstrucción de vía aérea <5%.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 301, Epstein-Barr Virus.",
