    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nEl aumento del tamaño esplénico puede ser rápido y producir molestias abdominales vagas y sensibilidad, mientras que la esplenomegalia masiva es poco frecuente.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Esplenomegalia: aproximadamente 50%.\r\n- Puede aumentar rápidamente.\r\n- Puede ocasionar molestias abdominales.\r\n- La esplenomegalia masiva es infrecuente.\r\n- La rotura esplénica es rara.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Esplenomegalia frecuente → crecimiento rápido posible → molestias abdominales/sensibilidad → rotura esplénica rara (~0,1%).\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- Dolor abdominal en mononucleosis obliga a tener presente el compromiso esplénico.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 301, Epstein-Barr Virus.",
