    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLas complicaciones neurológicas descritas incluyen meningitis, encefalitis, convulsiones, ataxia, metamorfopsia, mielitis transversa y parálisis.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- La meningitis o encefalitis sintomática es poco frecuente.\r\n- Las manifestaciones neurológicas pueden ser diversas.\r\n- La ataxia y las convulsiones están descritas.\r\n- La mielitis transversa y la parálisis también pueden presentarse.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Neurológicas: meningitis, encefalitis, convulsiones, ataxia, síndrome de Alicia en el País de las Maravillas, mielitis transversa y parálisis.\r\n- Hematológicas: anemia hemolítica, trombocitopenia, neutropenia, anemia aplásica.\r\n- Otras: miocarditis, nefritis intersticial, pancreatitis, parotiditis y orquitis.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- Para separar los grupos: VEB puede complicarse a nivel neurológico, hematológico, cardíaco, renal, pancreático y glandular.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 301, Epstein-Barr Virus.",
