    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nEl período de incubación de la mononucleosis infecciosa en adolescentes es de 30 a 50 días. En lactantes y niños pequeños, la infección primaria por VEB suele ser clínicamente silenciosa.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Incubación en adolescentes: 30-50 días.\r\n- La mayoría de los casos de infección primaria por VEB en lactantes y niños pequeños son clínicamente silenciosos.\r\n- En adolescentes y adultos jóvenes, la infección primaria suele manifestarse con la tríada clásica de fatiga, faringitis y linfadenopatía generalizada.\r\n- La enfermedad en adultos mayores de 40 años puede presentarse de manera atípica.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Adolescentes: incubación 30-50 días → inicio insidioso con malestar, fatiga, cefalea y odinofagia → tríada clásica: fatiga + faringitis + linfadenopatía generalizada.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- VEB en adolescente = incubación larga: 30-50 días.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 301, Epstein-Barr Virus.",
