    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nEl período de incubación de la infección adquirida por CMV es variable y prolongado, habitualmente de 28 a 60 días.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- El CMV es un herpesvirus humano ubicuo.\r\n- La infección puede adquirirse por diferentes vías y en distintos períodos de la vida.\r\n- Después de la infección primaria, el CMV establece una infección persistente de por vida.\r\n- Puede presentarse posteriormente reactivación o reinfección.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- El CMV puede adquirirse por exposición comunitaria, transmisión nosocomial, transmisión intrauterina, infección perinatal y transmisión sexual. Una vez adquirido, establece una infección persistente.\r\n\r\n⚡ CLAVE CONAREMCMV = incubación prolongada: 28-60 días.\r\n\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 302, Cytomegalovirus, págs. 2010-2015.",
