    "correctOptionIndex": 2,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nEn el huésped normal, la gran mayoría de las infecciones agudas por CMV no producen síntomas clínicos. Cuando aparecen manifestaciones, puede presentarse un síndrome similar a la mononucleosis.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- La mayoría de las infecciones en inmunocompetentes son asintomáticas.\r\n- Puede aparecer fiebre, malestar, fatiga y cefalea.\r\n- Puede existir adenopatía cervical.\r\n- Hasta un 20% puede presentar mononucleosis heterófilo-negativa.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- En el huésped normal: asintomático en la mayoría → ocasionalmente síndrome mononucleósico → fiebre, malestar, fatiga, cefalea y adenopatía cervical.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- CMV en inmunocompetente = generalmente asintomático.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 302, Cytomegalovirus, págs. 2012-2013.",
