    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nEntre los hallazgos clínicos de los lactantes con infección congénita sintomática, las petequias aparecen en aproximadamente 54%, siendo el hallazgo clínico más frecuente de los enumerados en la tabla.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Petequias: 54%.\r\n- Microcefalia: 35%.\r\n- Restricción del crecimiento intrauterino: 28%.\r\n- Prematuridad (<37 semanas): 24%.\r\n- Hepatoesplenomegalia: 19%.\r\n- Púrpura: 3%.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n**Hallazgos clínicos de CMV congénito sintomático:**\r\n- Petequias 54% → microcefalia 35% → RCIU 28% → prematuridad 24% → hepatoesplenomegalia 19% → púrpura 3%.\r\n- El 59% presenta ≥2 hallazgos clínicos y el 41% presenta un solo hallazgo.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- Entre los hallazgos clínicos de la tabla: petequias = el más frecuente (54%).\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 302, Cytomegalovirus, pág. 2013, tabla 302.2.",
