    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLa combinación de petequias, ictericia, hepatoesplenomegalia, microcefalia, restricción del crecimiento intrauterino y alteraciones intracraneales corresponde a una infección congénita sintomática por CMV.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Solo aproximadamente 10% de los recién nacidos infectados presentan manifestaciones clínicas al nacimiento.\r\n- Cerca del 90% no presenta manifestaciones clínicas al nacer.\r\n- La infección sintomática puede ser multisistémica.\r\n- Puede afectar hígado, sistema hematológico y sistema nervioso central.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Manifestaciones descritas: hepatoesplenomegalia, petequias, ictericia, microcefalia, RCIU y alteraciones intracraneales.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- RN + petequias + microcefalia + alteraciones intracraneales = pensar en CMV congénito.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 302, Cytomegalovirus, págs. 2012-2013.",
