    "correctOptionIndex": 1,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLa pérdida auditiva constituye la secuela a largo plazo más frecuente asociada a la infección congénita por CMV. Puede estar presente desde el nacimiento o aparecer posteriormente durante la infancia.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- La pérdida auditiva puede ser de aparición tardía.\r\n- Puede progresar con el tiempo.\r\n- Los niños con infección congénita requieren seguimiento auditivo.\r\n- El seguimiento debe mantenerse durante varios años.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Los lactantes con infección congénita sintomática deben tener seguimiento del sistema nervioso central, audición, desarrollo y función neuromuscular. Aproximadamente 11% de los infectados desarrollará algún grado de pérdida auditiva.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- CMV congénito → nunca olvidar seguimiento auditivo, incluso si inicialmente la audición es normal.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 302, Cytomegalovirus, pág. 2013.",
