    "correctOptionIndex": 3,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nEl diagnóstico de infección congénita por CMV requiere recuperar virus replicante o ácidos nucleicos virales durante las primeras 2-3 semanas de vida. Este límite permite diferenciar la infección congénita de una infección adquirida posteriormente.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Las muestras pueden incluir orina, saliva y sangre.\r\n- Los métodos incluyen cultivo viral, inmunofluorescencia y técnicas de amplificación de ácidos nucleicos.\r\n- La saliva ha demostrado ser sensible y específica para el cribado neonatal.\r\n- La cuantificación viral no predice de manera fiable la pérdida auditiva individual.\r\n\r\n⚡ REPASO ACTIVODiagnóstico de CMV congénito:\r\n\r\n- Demostración de virus/ácidos nucleicos → primeras 2-3 semanas de vida → muestras: orina, saliva o sangre.\r\n- Métodos mencionados: cultivo tisular, histopatología, detección de antígeno viral, amplificación de ácidos nucleicos, hibridación in situ y serología.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- CMV congénito = demostrar infección dentro de las primeras 3 semanas de vida.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 302, Cytomegalovirus, pág. 2014.",
