    "id": "semana17_ped_q110",
    "text": "¿Cuál es un hallazgo característico de la infección congénita por citomegalovirus?",
    "options": [
      "Adenopatías cervicales generalizadas",
      "Vesículas agrupadas en dermatomas",
      "Calcificaciones intracraneales periventriculares",
      "Exantema maculopapular centrípeto",
      "Hipertrofia amigdalina exudativa"
    ],
    "correctOptionIndex": 2,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nUn hallazgo característico de la infección congénita por CMV es la presencia de calcificaciones intracraneales periventriculares. La imagen presentada muestra múltiples áreas de calcificación con distribución periventricular bilateral.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- La infección congénita sintomática puede presentar microcefalia.\r\n- Puede asociarse con petequias, ictericia, hepatoesplenomegalia y restricción del crecimiento intrauterino.\r\n- Las alteraciones de la TC cerebral aparecen en aproximadamente 42% de los casos sintomáticos.\r\n- Puede existir pérdida auditiva, convulsiones y alteraciones motoras.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Hallazgos clínicos: petequias 54%, microcefalia 35%, RCIU 28%, prematuridad 24%, hepatoesplenomegalia 19% y púrpura 3%.\r\n- Hallazgos de laboratorio: ALT elevada 71%, hiperbilirrubinemia directa 54%, trombocitopenia 43% y alteraciones en TC cerebral 42%.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- CMV congénito + SNC → calcificaciones periventriculares.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 302, Cytomegalovirus, pág. 2013, fig. 302.1 y tabla 302.2.",
