    "id": "semana17_ped_q111",
    "text": "¿Cuál es el período de incubación habitual del exantema súbito (roséola infantil)?",
    "options": [
      "2 a 4 días",
      "3 a 5 días",
      "5 a 15 días",
      "14 a 21 días",
      "21 a 28 días"
    ],
    "correctOptionIndex": 2,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLa roséola infantil, causada principalmente por HHV-6B, presenta un período de incubación estimado de 5 a 15 días.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- El HHV-6B es la causa principal de roséola infantil.\r\n- La infección primaria ocurre principalmente durante la infancia.\r\n- La infección primaria por HHV-6B ocurre habitualmente entre los 6 y 9 meses de edad.\r\n- La infección por HHV-7 suele adquirirse posteriormente.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- La infección por HHV-6B se adquiere rápidamente durante la infancia: alrededor del 95% de los niños están infectados a los 2 años. La adquisición de HHV-7 ocurre más lentamente y aproximadamente 50% de los niños están infectados a los 6 años.\r\n\r\n⚡ CLAVE CONAREMRoséola → HHV-6B → incubación 5-15 días.\r\n\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 303, Roseola (Human Herpesviruses 6 and 7), págs. 2016-2018.",
