    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLas convulsiones son la complicación más frecuente de la roséola y casi siempre se relacionan con la fiebre. Las convulsiones febriles constituyen además la complicación más frecuente de la infección primaria documentada por HHV-6B.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Las convulsiones son la complicación más frecuente.\r\n- La mayoría son convulsiones febriles.\r\n- Aproximadamente 15% de los niños con infección primaria por HHV-6B presenta convulsiones febriles.\r\n- La mayoría son breves y generalizadas.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n**En una serie de niños con infección primaria por HHV-6B y convulsiones febriles:**\r\n- 93% presentó convulsiones generalizadas.\r\n- 29% presentó características focales.\r\n- 38% presentó convulsiones repetidas.\r\n- Aproximadamente 2-35 meses después, 17% presentó convulsiones febriles recurrentes.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- Roséola + complicación más frecuente = convulsión febril.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 303, Roseola (Human Herpesviruses 6 and 7), pág. 2018.",
