    "correctOptionIndex": 4,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLa adquisición de HHV-6B ocurre más tempranamente. La mayoría de los niños adquiere la infección durante la primera infancia, mientras que la infección por HHV-7 se adquiere de manera más lenta.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- HHV-6A, HHV-6B y HHV-7 pertenecen a la subfamilia de los betaherpesvirus.\r\n- HHV-6B es responsable de la mayoría de los casos de roséola.\r\n- HHV-7 también puede producir roséola.\r\n- Después de la infección primaria se establece latencia de por vida.\r\n- Puede producirse reactivación posteriormente.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- HHV-6B: alrededor del 95% de los niños está infectado a los 2 años.HHV-7: aproximadamente 50% está infectado a los 6 años.\r\n\r\n⚡ CLAVE CONAREMHHV-6B primero; HHV-7 después.\r\n\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 303, Roseola (Human Herpesviruses 6 and 7), pág. 2016.",
