    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLas convulsiones febriles constituyen la complicación más frecuente de la infección primaria documentada por HHV-6B. En general son breves y generalizadas.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Aproximadamente 15% presenta convulsiones febriles.\r\n- La mayoría son breves y generalizadas.\r\n- Puede existir recurrencia posterior.\r\n- La encefalitis es una complicación mucho menos frecuente.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Las complicaciones adicionales descritas en niños con infección primaria por HHV-6B incluyen encefalitis, encefalitis aguda diseminada, encefalitis autoinmune, cerebelitis, hepatitis y miocarditis, entre otras.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- Ante una pregunta de complicación típica/más frecuente de roséola, priorizar convulsión febril.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 303, Roseola (Human Herpesviruses 6 and 7), pág. 2018.",
