    "correctOptionIndex": 0,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nEl empeoramiento después de una mejoría inicial corresponde al patrón denominado “doble empeoramiento”, uno de los tres criterios clínicos para diagnosticar sinusitis bacteriana aguda.\r\n\r\n🔑 CONCEPTOS CLAVEEl doble empeoramiento consiste en:\r\n\r\n- Infección respiratoria inicial.\r\n- Mejoría clínica inicial.\r\n- Aparición posterior de nueva secreción nasal, tos diurna o fiebre.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Las infecciones virales de vías respiratorias superiores suelen presentar secreción nasal no purulenta, tos y fiebre inicial, con síntomas que generalmente no persisten más allá de 10-14 días. El empeoramiento después de una mejoría inicial orienta hacia sinusitis bacteriana.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- Mejora y después vuelve a empeorar = “doble empeoramiento” → sinusitis bacteriana aguda.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 429, Sinusitis, pág. 2555.",
