    "correctOptionIndex": 1,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLos principales patógenos bacterianos de la sinusitis bacteriana aguda pediátrica son S. pneumoniae (~30%), H. influenzae no tipificable (~50%) y M. catarrhalis (~10%).\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- H. influenzae no tipificable: aproximadamente 50%.\r\n- S. pneumoniae: aproximadamente 30%.\r\n- M. catarrhalis: aproximadamente 10%.\r\n- Cerca del 50% de H. influenzae y el 100% de M. catarrhalis producen β-lactamasa.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- S. aureus, otros estreptococos y anaerobios son causas poco frecuentes de sinusitis bacteriana aguda en niños. En la sinusitis crónica pueden recuperarse con mayor frecuencia otros microorganismos.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- Trío bacteriano pediátrico: H. influenzae + neumococo + Moraxella.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 429, Sinusitis, pág. 2554.",
