    "correctOptionIndex": 3,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nSegún la tabla del capítulo, el tratamiento empírico inicial para enfermedad leve a moderada es amoxicilina-clavulanato 45 mg/kg/día, dividido en dos dosis, durante 10 días.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Leve-moderada: amoxicilina-clavulanato 45 mg/kg/día VO, dividido cada 12 h.\r\n- Empeoramiento agudo o enfermedad grave: amoxicilina-clavulanato 90 mg/kg/día VO, dividido cada 12 h.\r\n- Hipersensibilidad tipo I a β-lactámicos: levofloxacino.\r\n- Hipersensibilidad no tipo I: cefpodoxima.\r\n- Infección grave que requiere hospitalización: tratamiento intravenoso.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- En niños hospitalizados con enfermedad grave, las opciones descritas incluyen ampicilina-sulbactam, ceftriaxona o levofloxacino IV.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- Sinusitis bacteriana leve-moderada → amoxicilina-clavulanato 45 mg/kg/día.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 429, Sinusitis, pág. 2556, tabla 429.2.",
