    "correctOptionIndex": 3,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLa celulitis periorbitaria produce principalmente eritema y edema de los tejidos que rodean el globo ocular. En cambio, la celulitis orbitaria afecta las estructuras intraorbitarias y puede ocasionar proptosis, quemosis, disminución de la agudeza visual, diplopía, alteración de los movimientos extraoculares y dolor ocular.\r\n\r\n🔑 CONCEPTOS CLAVEComplicaciones orbitarias:\r\n\r\n- Celulitis periorbitaria.\r\n- Celulitis orbitaria.\r\n\r\n**Complicaciones intracraneales:**\r\n- Absceso epidural.\r\n- Meningitis.\r\n- Trombosis del seno cavernoso.\r\n- Empiema subdural.\r\n- Absceso cerebral.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Periorbitaria: eritema + edema alrededor del ojo.Orbitaria: proptosis + quemosis + ↓ agudeza visual + diplopía + alteración de movimientos extraoculares + dolor ocular.\r\n- Signos de alarma intracraneal: alteración del estado mental, rigidez de nuca, déficit neurológico focal, convulsiones o aumento de presión intracraneal.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- Proptosis/diplopía/alteración de movimientos oculares = compromiso orbitario, no simple celulitis periorbitaria.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 429, Sinusitis, pág. 2556.",
