    "correctOptionIndex": 4,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLa halitosis es un síntoma menor, por lo que constituye la respuesta al EXCEPTO. Los demás forman parte de los síntomas mayores descritos en la tabla.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n**Síntomas MAYORES:**\r\n- Secreción nasal anterior purulenta.\r\n- Secreción nasal posterior purulenta o decolorada.\r\n- Congestión u obstrucción nasal.\r\n- Congestión o plenitud facial.\r\n- Dolor o presión facial, aislado o exacerbado al inclinarse hacia adelante.\r\n- Hiposmia o anosmia.\r\n- Fiebre, solo en sinusitis aguda.\r\n\r\n**Síntomas MENORES:**\r\n- Cefalea.\r\n- Dolor, presión o plenitud de oído.\r\n- Halitosis.\r\n- Dolor dental.\r\n- Tos.\r\n- Fiebre, en sinusitis subaguda o crónica.\r\n- Fatiga.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- La fiebre puede aparecer en ambas columnas, pero cambia según el contexto: es mayor en sinusitis aguda y menor en sinusitis subaguda o crónica.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- Halitosis + dolor dental + tos + cefalea = síntomas MENORES.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 429, Sinusitis, pág. 2555, tabla 429.1.",
