    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nDespués de un período de incubación de 2-5 días, la infección faríngea por estreptococo del grupo A suele manifestarse con inicio rápido de odinofagia significativa y fiebre.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Incubación: 2-5 días.\r\n- Inicio habitualmente rápido.\r\n- Odinofagia y fiebre son manifestaciones características.\r\n- Es relativamente infrecuente antes de los 2-3 años.\r\n- Es frecuente entre los 5-15 años.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- La faringitis estreptocócica ocurre durante todo el año, pero es más frecuente en invierno y primavera. Se disemina fácilmente entre hermanos y compañeros escolares y representa aproximadamente 15-30% de las faringitis en niños en edad escolar.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- Estreptococo del grupo A → incubación 2-5 días + inicio brusco.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 430, Acute Pharyngitis, pág. 2559.",
