    "correctOptionIndex": 4,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLa conjuntivitis es un hallazgo que orienta hacia etiología viral. El texto señala que diarrea, tos, coriza, ulceraciones, crup/laringitis/ronquera y conjuntivitis no se asocian con faringitis estreptocócica y aumentan la probabilidad de etiología viral.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n**Sugieren estreptococo del grupo A:**\r\n- Inicio brusco de odinofagia.\r\n- Edad 5-15 años.\r\n- Fiebre.\r\n- Cefalea.\r\n- Náuseas, vómitos o dolor abdominal.\r\n- Inflamación amigdalofaríngea.\r\n- Exudado amigdalino parcheado.\r\n- Petequias palatinas.\r\n- Adenopatía cervical anterior dolorosa.\r\n- Ausencia de tos o coriza.\r\n\r\n**Sugieren etiología viral:**\r\n- Conjuntivitis.\r\n- Coriza.\r\n- Tos.\r\n- Diarrea.\r\n- Ronquera.\r\n- Estomatitis ulcerativa.\r\n- Exantema viral.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- La clínica estreptocócica y viral puede superponerse; los hallazgos clínicos por sí solos pueden sobreestimar la probabilidad de etiología estreptocócica.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- Tos + coriza + conjuntivitis + ronquera + diarrea → pensar VIRAL.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 430, Acute Pharyngitis, págs. 2558-2559, tabla 430.2.",
