    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nEl cuadro reúne múltiples características que orientan a faringitis por estreptococo del grupo A: edad de 5-15 años, inicio brusco, fiebre, inflamación y exudado amigdalino, petequias palatinas, adenopatías cervicales anteriores dolorosas y ausencia de tos.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Grupo etario característico: 5-15 años.\r\n- Faringe eritematosa.\r\n- Amígdalas aumentadas y frecuentemente cubiertas por exudado.\r\n- Puede haber petequias en paladar blando y faringe posterior.\r\n- Adenopatías cervicales anteriores aumentadas y dolorosas son frecuentes.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Otros síntomas asociados incluyen cefalea, dolor abdominal, náuseas y vómitos. En ausencia de faringitis clínica, los síntomas gastrointestinales no deben atribuirse al estreptococo.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- Escolar + fiebre + exudado + adenopatía cervical anterior dolorosa + NO tos = estreptococo del grupo A.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 430, Acute Pharyngitis, pág. 2559.",
