    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLas petequias palatinas pueden sugerir etiología estreptocócica, pero no forman parte de los criterios de McIsaac descritos en el texto.\r\n\r\n🔑 CONCEPTOS CLAVESe otorga 1 punto por cada criterio:\r\n\r\n- Temperatura >38 °C.\r\n- Ausencia de tos.\r\n- Adenopatía cervical anterior dolorosa.\r\n- Aumento de tamaño o exudado amigdalino.\r\n- Edad 3-14 años.\r\n- Se resta 1 punto por edad ≥45 años.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Un puntaje de McIsaac ≥4 se asocia, en el mejor de los casos, con un valor predictivo positivo de aproximadamente 70% en niños con faringitis. Por ello, las pruebas de laboratorio son esenciales para un diagnóstico preciso.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- McIsaac: fiebre + no tos + ganglio cervical anterior doloroso + amígdala/exudado + edad.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 430, Acute Pharyngitis, págs. 2559-2560, tabla 430.3.",
