    "correctOptionIndex": 3,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nSegún el fragmento, Streptococcus pneumoniae (neumococo) es el patógeno bacteriano más frecuente en niños de 3 semanas a 5 años.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- 3 semanas-5 años: S. pneumoniae es el patógeno bacteriano más frecuente.\r\n- ≥5 años: Mycoplasma pneumoniae y Chlamydophila pneumoniae son los patógenos bacterianos más frecuentes.\r\n- Otras causas bacterianas en niños previamente sanos incluyen estreptococo del grupo A y S. aureus.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- La etiología de la neumonía varía con la edad. El texto destaca especialmente la diferencia entre los menores de 5 años y los niños de 5 años o más.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- 3 semanas-5 años → neumococo.≥5 años → Mycoplasma/Chlamydophila.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 449, Community-Acquired Pneumonia, pág. 2642.",
