    "correctOptionIndex": 1,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nEl fragmento señala específicamente que el virus respiratorio sincitial (VRS) y los rinovirus son los patógenos virales identificados con mayor frecuencia, particularmente en niños menores de 2 años.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n**Otros virus mencionados como causas de neumonía:**\r\n- Influenza.\r\n- Metapneumovirus humano.\r\n- Parainfluenza.\r\n- Adenovirus.\r\n- Enterovirus.\r\n- Coronavirus, incluido SARS-CoV-2.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- El VRS es particularmente grave en lactantes y niños pequeños, mientras que los virus influenza pueden producir enfermedad y hospitalización excesivas en todos los grupos etarios.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- <2 años + neumonía viral → VRS/rinovirus son los más identificados.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, capítulo 449, Community-Acquired Pneumonia, pág. 2642.",
