    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nMycoplasma pneumoniae se relaciona característicamente con neumonía en adolescentes y con epidemias entre el verano y el otoño.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- M. pneumoniae: adolescentes.\r\n- Presentación epidémica: verano a otoño.\r\n- Constituye una causa bacteriana común de neumonía.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Las causas bacterianas comunes incluyen Streptococcus pneumoniae, estreptococo del grupo B, estreptococo del grupo A, Staphylococcus aureus, Mycoplasma pneumoniae, Chlamydophila pneumoniae, Chlamydia trachomatis, anaerobios mixtos y enterobacterias gramnegativas.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- Adolescente + epidemia verano-otoño → Mycoplasma pneumoniae.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, cap. 449, pág. 2643.",
