    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLas enterobacterias gramnegativas se asocian con neumonía nosocomial. Los anaerobios mixtos se relacionan con aspiración, C. trachomatis con lactantes y C. pneumoniae con adolescentes.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Enterobacterias gramnegativas → neumonía nosocomial.\r\n- Anaerobios mixtos → neumonía por aspiración.\r\n- C. trachomatis → lactantes.\r\n- C. pneumoniae → adolescentes.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Entre las asociaciones bacterianas destacan S. pneumoniae con consolidación y empiema; S. aureus con neumatoceles y empiema; anaerobios mixtos con aspiración; y enterobacterias gramnegativas con infección nosocomial.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- Aspiración → anaerobios mixtos. Nosocomial → enterobacterias gramnegativas.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, cap. 449, pág. 2643.",
