    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nEl complejo Mycobacterium avium se asocia con pacientes inmunocomprometidos, particularmente aquellos infectados por VIH.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- M. avium complex → inmunocompromiso, especialmente VIH.\r\n- M. tuberculosis → viaje a región endémica o exposición a personas de alto riesgo.\r\n- Otras micobacterias no tuberculosas → inmunocompromiso y fibrosis quística.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Las causas micobacterianas comprenden Mycobacterium tuberculosis, complejo Mycobacterium avium y otras micobacterias no tuberculosas.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- Inmunocompromiso, especialmente VIH → complejo Mycobacterium avium.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, cap. 449, pág. 2643.",
