    "id": "semana17_ped_q149",
    "text": "Un lactante presenta neumonía complicada con formación de neumatoceles y empiema. El agente etiológico más probable es:",
    "options": [
      "Streptococcus pneumoniae",
      "Estreptococo del grupo A",
      "Staphylococcus aureus",
      "Mycoplasma pneumoniae",
      "Chlamydia trachomatis"
    ],
    "correctOptionIndex": 2,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nStaphylococcus aureus se asocia con neumatoceles y empiema, especialmente en lactantes, y también puede causar neumonía nosocomial.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- S. aureus → neumatoceles + empiema.\r\n- S. pneumoniae → consolidación + empiema.\r\n- Estreptococo del grupo A → empiema.\r\n- S. aureus también se relaciona con lactantes y neumonía nosocomial.\r\n\r\n⚡ REPASO ACTIVOComplicaciones y asociaciones bacterianas:\r\n\r\n- Streptococcus pneumoniae → consolidación, empiema.\r\n- Estreptococo del grupo A → empiema.\r\n- Staphylococcus aureus → neumatoceles, empiema.\r\n- Anaerobios mixtos → aspiración.\r\n- Enterobacterias gramnegativas → neumonía nosocomial.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- Neumatocele + empiema → Staphylococcus aureus.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, cap. 449, pág. 2643.",
