    "id": "semana17_ped_q150",
    "text": "Un niño desarrolla neumonía después de exponerse a aerosoles contaminados provenientes del sistema de agua de un hospital. El diagnóstico infeccioso más probable es:",
    "options": [
      "Histoplasmosis",
      "Brucelosis",
      "Legionelosis",
      "Tularemia",
      "Psitacosis"
    ],
    "correctOptionIndex": 2,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLa exposición a aerosoles contaminados, incluidos los sistemas de agua hospitalaria y los enfriadores de aire, se relaciona con legionelosis.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Aerosoles contaminados → legionelosis.\r\n- Sistemas de agua hospitalaria → legionelosis.\r\n- Enfriadores de aire → legionelosis.\r\n\r\n⚡ REPASO ACTIVOExposiciones ambientales:\r\n\r\n- Aerosoles contaminados → legionelosis.\r\n- Pelo de cabra, lana cruda o pieles animales → ántrax.\r\n- Leche no pasteurizada → brucelosis.\r\n- Guano de murciélago o suelo enriquecido con excrementos de aves → histoplasmosis.\r\n- Agua contaminada con orina animal → leptospirosis.\r\n- Excrementos, orina o saliva de roedores → hantavirus.\r\n- Exposición potencial a bioterrorismo → ántrax, peste, tularemia.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- Aerosoles + sistema de agua hospitalaria → legionelosis.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, cap. 449, pág. 2644.",
