    "correctOptionIndex": 3,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLa exposición a loros, periquitos, cacatúas, palomas y pavos se relaciona con psitacosis.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Aves → psitacosis.\r\n- Conejos, zorros y ardillas → tularemia.\r\n- Ganado, cabras y cerdos → ántrax o brucelosis.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Las exposiciones zoonóticas permiten orientar rápidamente la etiología: aves → psitacosis; matadero/veterinaria → brucelosis; moscas/garrapatas → tularemia; determinados roedores → peste; cabras, ganado y ovejas → fiebre Q.\r\n\r\n⚡ CLAVE CONAREMLoros/periquitos + neumonía → psitacosis.\r\n\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, cap. 449, pág. 2644.",
