    "correctOptionIndex": 2,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLa residencia o viaje a esas regiones del sudoeste de Estados Unidos se relaciona con coccidioidomicosis.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- San Joaquín Valley → coccidioidomicosis.\r\n- Sur de California → coccidioidomicosis.\r\n- Sur de Arizona y Nuevo México → coccidioidomicosis.\r\n\r\n⚡ REPASO ACTIVO — VIAJES\r\n\r\n- San Joaquín Valley, sur de California, sudoeste de Texas, sur de Arizona, Nuevo México → coccidioidomicosis.\r\n- Valles de Mississippi u Ohio, estados de los Grandes Lagos, Caribe, Centroamérica o África → histoplasmosis, blastomicosis.\r\n- Sur de China → influenza aviar.\r\n- Península arábiga → MERS-CoV.\r\n- Sudeste asiático → paragonimiasis, melioidosis.\r\n- Indias Occidentales, Australia o Guam → melioidosis.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- San Joaquín + Arizona/Nuevo México → coccidioidomicosis.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, cap. 449, pág. 2644.",
