    "correctOptionIndex": 1,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nKingella kingae constituye una etiología relativamente frecuente en niños menores de 4 años, especialmente con la mejoría de los métodos de cultivo y PCR.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Edad → <4 años.\r\n- K. kingae → causa relativamente frecuente.\r\n- Cultivos mejorados → aumentan detección.\r\n- PCR → aumenta detección.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Las asociaciones por edad de mayor rendimiento son: S. aureus a cualquier edad; S. pneumoniae especialmente durante los primeros 2 años; K. kingae en menores de 4 años; estreptococo del grupo B en neonatos; y gonococo en adolescentes sexualmente activos.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- <4 años + artritis séptica → recordar Kingella kingae.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, cap. 726, pág. 4291.",
