    "correctOptionIndex": 3,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nEl estreptococo del grupo B constituye una causa importante de artritis séptica en neonatos.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Neonato → estreptococo del grupo B.\r\n- Candida también puede complicar infecciones sistémicas neonatales.\r\n- S. aureus continúa siendo el agente más frecuente globalmente.\r\n\r\n⚡ REPASO ACTIVOEtiología orientada por edad:\r\n\r\n- Todas las edades → S. aureus.\r\n- Primeros 2 años → mayor importancia de S. pneumoniae.\r\n- <4 años → K. kingae.\r\n- Neonatos → estreptococo del grupo B.\r\n- Adolescentes sexualmente activos → gonococo.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- Neonato + artritis séptica → estreptococo B entre los agentes clave.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, cap. 726, pág. 4291.",
