    "id": "semana17_ped_q187",
    "text": "Un adolescente sexualmente activo presenta artritis infecciosa y tenosinovitis que comprometen principalmente articulaciones pequeñas. El microorganismo más relacionado es:",
    "options": [
      "Neisseria gonorrhoeae",
      "Kingella kingae",
      "Streptococcus pneumoniae",
      "Estreptococo del grupo B",
      "Neisseria meningitidis"
    ],
    "correctOptionIndex": 0,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nEn adolescentes sexualmente activos, el gonococo constituye una causa frecuente de artritis séptica y tenosinovitis. Habitualmente compromete articulaciones pequeñas o produce una infección monoarticular de una articulación grande, como la rodilla.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Adolescente sexualmente activo → gonococo.\r\n- Puede causar artritis séptica.\r\n- Puede acompañarse de tenosinovitis.\r\n- Puede afectar articulaciones pequeñas.\r\n- Puede causar monoartritis de una articulación grande.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- El gonococo constituye una etiología característica en adolescentes sexualmente activos. Puede presentarse como artritis y tenosinovitis de pequeñas articulaciones o como infección monoarticular de una articulación grande, particularmente la rodilla.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- Adolescente sexualmente activo + artritis/tenosinovitis → gonococo.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, cap. 726, pág. 4291.",
