    "correctOptionIndex": 4,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLa etiología microbiana se confirma aproximadamente en 65% de los casos de artritis séptica.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Confirmación microbiológica → aproximadamente 65%.\r\n- No todos los cuadros tratados como artritis bacteriana representan infección primaria.\r\n- Algunas artritis pueden ser reactivas.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Algunos cuadros tratados como artritis bacteriana corresponden realmente a artritis reactiva posterior a infecciones extraarticulares, como gastroenteritis o infección genitourinaria. La enfermedad de Lyme puede producir artritis semejante a otros trastornos reumatológicos y típicamente no es supurativa.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- Artritis séptica → etiología demostrable en aproximadamente 2 de cada 3 casos.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, cap. 726, pág. 4291.",
