    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLa rodilla constituye la localización más frecuente de la artritis bacteriana hematógena, representando aproximadamente 35% de los casos. La cadera ocupa el segundo lugar, con aproximadamente 25%.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Rodilla → ≈35%.\r\n- Cadera → ≈25%.\r\n- Tobillo → ≈10%.\r\n- Codo → ≈10%.\r\n- Hombro → ≈5%.\r\n\r\n⚡ REPASO ACTIVO — DISTRIBUCIÓN COMPLETA\r\n\r\n- Rodilla: ≈35%.\r\n- Cadera: ≈25%.\r\n- Tobillo: ≈10%.\r\n- Codo: ≈10%.\r\n- Hombro: ≈5%.\r\n- Muñeca: ≈4%.\r\n- Articulaciones pequeñas: ≈1-2%.\r\n- Esta distribución corresponde a artritis bacteriana hematógena y excluye la enfermedad de Lyme y la artritis postinfecciosa por complejos inmunes.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- Artritis séptica hematógena → rodilla primero (35%), cadera segundo (25%).\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, cap. 726, tabla 726.1.",
