    "correctOptionIndex": 2,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nLa mayoría de las artritis sépticas son monoarticulares. La presentación clínica varía con la edad y puede ser especialmente sutil en los neonatos.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- La mayoría → monoarticular.\r\n- Neonatos → presentación inicial sutil.\r\n- La edad modifica la expresión clínica.\r\n- Miembros inferiores → cojera o rechazo a caminar.\r\n\r\n⚡ REPASO ACTIVO — MANIFESTACIONES CLÍNICAS\r\n\r\n- La mayoría de las artritis sépticas son monoarticulares.\r\n- Neonatos → pseudoparálisis o dolor que limita el movimiento voluntario.\r\n- Neonatos y lactantes pequeños → asociación frecuente con osteomielitis adyacente por diseminación transfisaria.\r\n- Lactantes mayores y niños → fiebre, dolor, edema, eritema y calor articular.\r\n- Articulaciones pélvicas o de miembros inferiores → cojera o rechazo a caminar.\r\n- Eritema y edema aparecen antes que en la osteomielitis por la localización más superficial de la sinovial.\r\n- Cadera → excepción por su localización profunda.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- Artritis séptica = habitualmente monoarticular.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, cap. 726.",
