    "correctOptionIndex": 0,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nEn neonatos, los signos iniciales pueden ser poco evidentes. La pseudoparálisis o el dolor que limita el movimiento voluntario, incluso durante el cambio de pañal, constituye una presentación característica.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Neonato → signos sutiles.\r\n- Pseudoparálisis → dato de alto rendimiento.\r\n- Dolor con movilización → orientador.\r\n- Puede coexistir osteomielitis adyacente.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- La artritis séptica neonatal puede acompañarse de osteomielitis adyacente por propagación transfisaria. La osteomielitis contigua a una articulación infectada también puede aparecer a cualquier edad.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- Neonato + pseudoparálisis → pensar en infección osteoarticular.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, cap. 726.",
