    "id": "semana17_ped_q194",
    "text": "Un niño presenta marcada tumefacción de la rodilla con dolor relativamente leve y poca limitación del movimiento. El diagnóstico que mejor corresponde es:",
    "options": [
      "Artritis séptica supurativa",
      "Osteomielitis hematógena",
      "Artritis gonocócica",
      "Artritis de Lyme",
      "Piomiositis adyacente"
    ],
    "correctOptionIndex": 3,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nEn la artritis de Lyme, la tumefacción articular puede ser muy prominente y desproporcionada respecto al dolor y a la limitación del rango de movimiento, en comparación con una artritis supurativa.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Tumefacción importante.\r\n- Dolor relativamente menor.\r\n- Limitación de movimiento relativamente menor.\r\n- Predilección por grandes articulaciones.\r\n- Rodillas y caderas → localizaciones principales.\r\n- Puede ser monoarticular o pauciarticular.\r\n\r\n⚡ REPASO ACTIVO — LYME\r\n\r\n- Predilección por grandes articulaciones.\r\n- Especialmente rodillas y caderas.\r\n- Presentación monoarticular o pauciarticular.\r\n- Tumefacción llamativa.\r\n- Dolor y limitación proporcionalmente menores que en artritis supurativa.\r\n\r\n⚡ CLAVE CONAREM\r\n\r\n- Articulación muy hinchada pero relativamente poco dolorosa → Lyme.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, cap. 726.",
