    "id": "semana17_ped_q200",
    "text": "Ministerio de Salud Pública y Bienestar Social (MSPyBS). Dengue: Guía de Manejo Clínico , 2012. Sección II: Fases de la enfermedad (Fase febril).\n¿Qué complicación clínica puede presentarse durante la fase de recuperación en un paciente con dengue al cual se le administran cantidades excesivas de fluidos durante la fase crítica?",
    "options": [
      "Coagulación intravascular diseminada con sangrado masivo",
      "Acidosis metabólica refractaria secundaria a choque hipovolémico",
      "Edema pulmonar o falla cardíaca congestiva por reabsorción de fluidos",
      "Aumento brusco de la viremia con falla hepática fulminante",
      "Hemoconcentración severa con elevación progresiva del hematocrito"
    ],
    "correctOptionIndex": 2,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\n«Edema pulmonar o falla cardíaca congestiva por reabsorción de fluidos» es la correcta porque la guía establece explícitamente que la administración excesiva de fluidos durante la fase crítica puede desencadenar distrés respiratorio, edema pulmonar o falla cardíaca congestiva a partir de la reabsorción del derrame pleural y la ascitis en la etapa de recuperación.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Fisiopatología de la sobrecarga: Durante la recuperación se reabsorbe gradualmente el líquido acumulado en tercer espacio (ascitis y derrame pleural). Si se sobrecargó al paciente con fluidoterapia intravenosa en la fase crítica, este volumen reabsorbido sobrecarga el lecho intravascular.\r\n- Complicaciones respiratorias y cardiovasculares: El exceso de volumen en esta fase puede originar distrés respiratorio, edema agudo de pulmón y falla cardíaca congestiva.\r\n- Cinética viral vs. serología: La viremia cae al finalizar la fase febril, dando paso a la elevación de anticuerpos IgM/IgG en las fases crítica y de recuperación.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n**Eventos clínicos potenciales según la fase (Figura 1):**\r\n- Fase Febrero (Días 1 a 3): Deshidratación.\r\n- Fase Crítica (Días 4 a 6): Choque y sangrados (con daño de órgano).\r\n- Fase de Recuperación (Días 7 a 10): Reabsorción de sobrecarga.\r\n\r\n**Cinética laboratorial e inmunológica:**\r\n- Hematocrito: Pico elevado en fase crítica (máxima fuga) y normalización/descenso en recuperación.\r\n- Plaquetas: Punto más bajo en fase crítica y ascenso sostenido durante la recuperación.\r\n- Viremia / Serología: Viremia alta al inicio (días 1 a 4–5); elevación de IgM/IgG a partir de la fase crítica en adelante.\r\n\r\n**📖 Referencia:**",
