    "correctOptionIndex": 1,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\n«Investigación de rabdomiólisis mediante dosaje de CK, aldolasa y LDH, y asistencia respiratoria mecánica» es la correcta porque el Grupo D abarca pacientes con falla respiratoria grave o inestabilidad hemodinámica tributaria de UTI; su protocolo de laboratorio incluye específicamente la investigación de rabdomiólisis mediante el perfil enzimático CK-Aldolasa-LDH, gasometría, crasis sanguínea, ecocardiografía e indicación de asistencia respiratoria mecánica (ARM).\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Criterios de inclusión Grupo D: Dificultad respiratoria grave (quejido, retracción generalizada, cianosis, aleteo, cabeceo), incapacidad de sostener SaO2≥92% con FiO2 > 60%, gasometría conP a F i O2​≤175con máscara con reservorio tributario de IOT/ARM, o inestabilidad hemodinámica.\r\n- Lugar de atención: Unidad de Cuidados Intensivos (ITU) con aislamiento respiratorio y de contacto.\r\n- Manejo del choque en UTI: Corregir acidosis, hipoglicemia e hipocalcemia; ante persistencia de signos de choque, valorar etiología por miocardiopatía/insuficiencia cardíaca o sepsis bacteriana agregada.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n**Grupo D - Criterios de Inclusión y Nivel UTI:**\r\n- Dificultad respiratoria grave: quejido espiratorio, retracción generalizada, cianosis central, aleteo nasal, cabeceo.\r\n- Incapacidad para mantener SaO2≥92% con aporte de O2 > 60%.\r\n- Gasometría (P a F i O2​≤175con máscara con reservorio) con requerimiento de IOT.\r\n- Inestabilidad hemodinámica con o sin requerimiento de IOT.\r\n- Rx con infiltrado intersticial uni o bilateral.\r\n\r\n**Protocolo de Manejo Grupo D:**\r\n- Nivel: Unidad de Cuidados Intensivos (aislamiento respiratorio y contacto; monitoreo minuto a minuto).\r\n- Laboratorio específico: Hemograma, PCR, crasis, urea, creatinina, glicemia, GOT/GPT, electrolitos, gasometría, investigación de rabdomiólisis (CK-Aldolasa-LDH), Rx tórax, ecocardiografía.\r\n- Tratamiento: Iniciar en el primer lugar de atención; BRA",
