    "correctOptionIndex": 1,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\n«Grupo B (Escenario 2): Cuadro compatible con factores de riesgo sin signos de alarma -> Hospital distrital en sala individual o control médico domiciliario diario -> Laboratorio básico e hidratación por vía oral supervisada» es la correcta porque el Grupo B (Escenario 2) incluye a los pacientes con sospecha de COVID-19 que presentan factores de riesgo de complicaciones (como edad menor o igual a 2 años, enfermedades crónicas o factores sociales), sin signos de alarma ni insuficiencia respiratoria. La guía establece su internación en hospital distrital en sala individual (o control médico domiciliario diario), toma de laboratorio (hemograma, plaquetas, glicemia, urea, creatinina, GOT, GPT), líquidos por vía oral supervisados ​​y reevaluación clínica diaria.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Grupo A (Escenario 1): Sin factores de riesgo, sin alarma, sin falla grave -> Aislamiento domiciliario, hidratación adecuada, paracetamol 15 mg/kg cada 6 horas (prohibidos salicilatos en menores de 18 años) y control si la fiebre dura más de 48 horas.\r\n- Grupo B (Escenario 2): Con factores de riesgo, sin alarma -> Hospital distrital / control domiciliario diario, laboratorio básico, hidratación oral supervisada y reevaluación diaria.\r\n- Grupo C (Escenario 3): Con signos de alarma/criterios de gravedad -> Hospital regional o de referencia en aislamiento, oxígeno si la saturación es de 95% o menor (bigotera hasta 2 L/min, mascarilla si es mayor a 2 L/min), oseltamivir si lleva menos de 48 horas de fiebre y considere lopinavir/ritonavir.\r\n- Grupo D (Escenario 4): Con dificultad respiratoria grave o inestabilidad hemodinámica -> Unidad de Cuidados Intensivos (UTI), asistencia respiratoria mecánica, panel de rabdomiólisis (CK, aldolasa, LDH), antiviral/inmunomodulador y manejo de choque.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n**Resumen Comparativo de los 4 Escenarios:**\r\n- Grupo A (Escenario 1): Compatible (+), Factores de riesgo (-), Signos de alarma (-), Falla respiratoria/hemodinámica (-). Nivel: Domicilio. Conducta: Paracetamol 15 mg/kg cada 6 horas, no usar salicilatos, hidratación adecuada, consultar si la fiebre supera las 48 horas.\r\n- Grupo B (Escenario 2): Compatible (+), Factores de riesgo (+), Signos de alarma (-), Falla respiratoria/hemodinámica (-). Nivel: Hospital distrital (sala individual) o control domiciliario diario. Conducta: Laboratorio (hemograma, plaquetas, glicemia, urea, creatinina, GOT, GPT), Rx si hay tos persistente, hidratación oral supervisada.\r\n- Grupo C (Escenario 3): Compatible (+), Factores de riesgo (+/-), Signos de alarma (+), Falla respiratoria/hemodinámica (-). Nivel: Hospital regional o de referencia. Conducta: Laboratorio con PCR y gases, Rx tórax, O2 si saturación es 95% o menor, oseltamivir si fiebre menor a 48 horas, salbutamol si hay sibilancias.\r\n- Grupo D (Escenario 4): Compatible (+), Factores de riesgo (+/-), Signos de alarma (+), Falla respiratoria/hemodinámica (+). Nivel: Unidad de Cuidados Intensivos (UTI). Conducta: Asistencia respiratoria mecánica, monitoreo minuto a minuto, perfil de rabdomiólisis (CK-Aldolasa-LDH), crasis, ecocardiografía, antivirales y corrección de choque/acidosis.\r\n\r\n**📖 Referencia:**",
