    "correctOptionIndex": 2,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA «En los humanos, los síntomas de la enfermedad aparecen tras un período de incubación intrínseca general de 3 a 7 días (rango: 1-12 días)» es la correcta porque el texto oficial describe textualmente que, tras la picadura de un mosquito infectado, los síntomas en los humanos se presentan generalmente tras un período de incubación intrínseca de 3 a 7 días, con un rango posible de 1 a 12 días.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Período de incubación extrínseco: Se desarrolla en el mosquito y tiene una duración promedio de 10 días tras alimentarse de una persona en fase de viremia.\r\n- Período de incubación intrínseco: Ocurre en el ser humano tras la picadura del mosquito infectado; la clínica se manifiesta generalmente entre 3 y 7 días (rango: 1 a 12 días ).\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- ¿Cuánto dura en promedio el período de incubación extrínseco (en el vector)?\r\n- ↳ 10 días .\r\n- ¿Cuál es el tiempo habitual y el rango del período de incubación intrínseco (en humanos)?\r\n- ↳ 3 a 7 días (rango: 1 a 12 días ).\r\n- ¿En qué fase el huésped adquiere el virus el mosquito?\r\n- ↳ Durante el período de viremia .\r\n- 📖 Referencia: Guía de manejo clínico de la enfermedad por el virus Chikungunya y organización de servicios de salud (MSPyBS, 2023) . Sección: Períodos de incubación, pág. 18 /Figura 1.",
