    "correctOptionIndex": 1,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA La fase aguda (5 a 10 días / primeras 3 semanas) cursa con alteraciones de laboratorio que incluyen leucopenia, trombocitopenia, elevación de transaminasas, LDH y proteína C reactiva, además de fiebre, artralgia severa, mialgias, cefalea, edema, náuseas, vómitos, astenia y anorexia (las imágenes articulares no están indicadas salvo diagnóstico diferencial); en contraste, la fase subaguda (21 días al final del 3er mes) cursa con persistencia del dolor, lesiones multiformes, artralgias inflamatorias, artritis, tenosinovitis/bursitis, astenia intensa y alteraciones neuropsicológicas; y la fase crónica (a partir del 4to mes) se define por síntomas >3 meses, posible artropatía destructiva y ausencia de cambios significativos de laboratorio o radiografías.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Fase Aguda (5 a 10 días / primeras 3 semanas): Fiebre alta (continua/intermitente), artralgia severa (discapacidad/postración), mialgias, cefalea, edema facial y de extremidades, náuseas, vómitos, astenia, anorexia. Laboratorio: leucopenia, trombocitopenia, transaminasas elevadas, LDH elevada, PCR elevada. Imágenes: no indicadas salvo diagnóstico diferencial.\r\n- Fase Subaguda (21 días hasta el final del 3er mes): Persistencia de dolores articulares, lesiones multiformes, artralgias inflamatorias, artritis, sinovitis con/sin derrame, tenosinovitis o bursitis. Astenia intensa y alteraciones neuropsicológicas. Imágenes: radiografía o ecografía prioritarias si la clínica no es concluyente. Opinión de especialista en poliartritis dolorosa e incapacitante.\r\n- Fase Crónica (a partir del 4to mes): Persistencia de síntomas >3 meses (meses a varios años) con manifestaciones similares a la subaguda. Puede desarrollar artropatía/artritis destructiva semejante a artritis reumatoide o psoriásica. Sin cambios significativos de laboratorio ni radiografías. Factores de riesgo: edad avanzada y trastornos articulares preexistentes.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- ¿Cuáles son las tres fases clínicas del Chikungunya y sus marcos temporales?\r\n- ↳ Aguda (5 a 10 días / primeras 3 semanas), Subaguda (21 días hasta final del 3er mes) y Crónica (a partir del 4to mes / >3 meses).\r\n- ¿Qué alteraciones laboratoriales caracterizan a la fase aguda?\r\n- ↳ Leucopenia, trombocitopenia, transaminasas elevadas, LDH elevada y PCR elevada.\r\n- ¿Cuándo son prioritarias la radiografía o ecografía articular?\r\n- ↳ En la fase subaguda cuando el análisis clínico no es concluyente (en la aguda solo por diagnóstico diferencial).\r\n- ¿Qué complicaciones articulares y factores de riesgo definen a la fase crónica?\r\n- ↳ Artropatía destructiva (tipo AR o psoriásica); Factores de riesgo: edad avanzada y patología articular previa.\r\n- 📖 Referencia: Guía de manejo clínico de la enfermedad por el virus Chikungunya y organización de servicios de salud (MSPyBS, 2023) . Sección: Tabla 2. Fases clínicas del Chikungunya, pág. 22.",
