    "correctOptionIndex": 3,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA Los factores de riesgo identificados para la persistencia prolongada de síntomas en la fase crónica (a partir del 4to mes) son la edad avanzada y los trastornos articulares preexistentes; en esta fase el paciente puede evolucionar a artropatía destructiva semejante a artritis reumatoide, a diferencia de la fase aguda dominada por fiebre y laboratorio alterado (leucopenia, plaquetopenia) y la fase subaguda caracterizada por sinovitis, bursitis y compromiso neuropsicológico.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Fase Aguda (5 a 10 días / 1ras 3 semanas): Inicio súbito con fiebre alta, dolor articular severo discapacitante, mialgias, edema y alteraciones de reactantes de fase aguda y hemograma.\r\n- Fase Subaguda (21 días hasta el final del 3er mes): Persistencia de dolor con artritis, bursitis, tenosinovitis, lesiones dérmicas multiformes, compromiso neuropsicológico y requerimiento de imágenes ante dudas diagnósticas.\r\n- Fase Crónica (a partir del 4to mes): Persistencia sintomática por meses a años. Riesgo de artropatía destructiva similar a artritis reumatoide o psoriásica. Sin cambios significativos en laboratorio ni radiografías. Factores predisponentes: edad avanzada y trastornos articulares previos.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- ¿A partir de qué momento temporal se define formalmente la fase crónica?\r\n- ↳ A partir del 4to mes (síntomas que superan los 3 meses).\r\n- ¿A qué patologías inflamatorias pueden asemejarse a la artropatía destructiva crónica?\r\n- ↳ Artritis reumatoide o artritis psoriásica.\r\n- ¿Cuáles son los dos factores de riesgo de cronicidad sintomática?\r\n- ↳ Edad avanzada y trastornos articulares preexistentes.\r\n- 📖 Referencia: Guía de manejo clínico de la enfermedad por el virus Chikungunya y organización de servicios de salud (MSPyBS, 2023) . Sección: Tabla 2. Fases clínicas del Chikungunya, pág. 22.",
