    "id": "semana17_ped_q224",
    "text": "En la comparación clínica y de laboratorio clásica entre Chikungunya y Dengue, ¿cuál de los siguientes parámetros se presenta con mayor intensidad o frecuencia en el Chikungunya frente al Dengue?",
    "options": [
      "Neutropenia",
      "Trombocitopenia",
      "Mialgias",
      "Linfopenia",
      "Hematocrito elevado"
    ],
    "correctOptionIndex": 3,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA La linfopenia se presenta con máxima frecuencia/intensidad (+++) en Chikungunya comparado con Deng (++), al igual que la fiebre (>39°) y las artralgias (ambas +++ en Chikungunya frente a ++ y +/- en Dengue respectivamente).\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Parámetros predominantes en Chikungunya (+++): Fiebre >39° (+++ vs ++), artralgias (+++ vs +/-) y linfopenia (+++ vs ++).\r\n- Parámetros de intensidad intermedia en Chikungunya (++): Cefaleas (++ en ambos), erupción (++ vs +) y leucopenia (++ vs +++).\r\n- Parámetros predominantes en Dengue: Mialgias (++ vs +), discrasias sanguíneas (++ vs +/-), shock (+ vs -), leucopenia (+++ vs ++), neutropenia (+++ vs +++ en dengue vs + en chikungunya), hematocrito elevado (++ vs +) y trombocitopenia (+++ vs +).\r\n- Epidemia en Paraguay: Se describieron variaciones respecto a la literatura tradicional, observándose mayor frecuencia de náuseas y vómitos, deposiciones líquidas que llevan a deshidratación rápida y shock, discrasias sanguíneas, y compromiso neurológico y cardiovascular.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- ¿Qué alteraciones clínicas y laboratoriales son marcadamente más intensas/frecuentes (+++) en Chikungunya que en Dengue?\r\n- ↳ Fiebre >39°, artralgias y linfopenia.\r\n- ¿Qué hallazgos laboratorios clásicos son marcadamente más intensos/frecuentes (+++) en Dengue?\r\n- ↳ Leucopenia, neutropenia y trombocitopenia.\r\n- ¿Qué manifestaciones atípicas/diferenciales se observaron en la epidemia de Chikungunya en Paraguay?\r\n- ↳ Náuseas, vómitos, deposiciones líquidas con deshidratación rápida y shock, discrasias sanguíneas y compromiso neurológico y cardiovascular.\r\n- 📖 Referencia: Guía de manejo clínico de la enfermedad por el virus Chikungunya y organización de servicios de salud (MSPyBS, 2023) . Sección: Diagnóstico diferencial con el Dengue, Tabla 5, pág. 25.",
