    "tema": "Infectología",
    "subtema": "Laringotraqueobronquitis (Crup)",
    "subtema_grupo": "Infecciones Respiratorias de Vías Aéreas",
    "module": "Semana 17 - Pediatría",
    "pagina": "📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, Capítulo 433, pp. 2569-2572."
