    "id": "semana17_ped_q243",
    "text": "¿Cuál es el rango del período de incubación característico de la infección por Bordetella pertussis antes del inicio de los síntomas?",
    "options": [
      "3 a 12 días.",
      "1 a 2 días.",
      "14 a 21 días.",
      "21 a 28 días.",
      "30 a 45 días."
    ],
    "correctOptionIndex": 0,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\na) [CORRECTA]: La fase catarral de la tos ferina comienza de forma insidiosa tras un período de incubación que oscila entre 3 y 12 días.\r\n\r\nb) [Incorrecta]: Un período menor a 3 días es característico de otras infecciones virales como la influenza, pero es demasiado corto para B. pertussis .\r\n\r\nc) [Incorrecta]: De 14 a 21 días corresponde a la duración estimada de cuadros prolongados de tos inespecíficas en adolescentes y adultos, no al intervalo de incubación.\r\n\r\nd) [Incorrecta]: De 21 a 28 días excede el rango habitual reportado para la incubación de la bacteria.\r\n\r\ne) [Incorrecta]: Los períodos mayores a un mes no corresponden a la primoinfección por Bordetella .\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n**Cronología de las fases en niños no inmunizados:**\r\n- Incubación: 3 a 12 días.\r\n- Fase catarral: 1 a 2 semanas.\r\n- Fase paroxística: 2 a 6 semanas.\r\n- Fase de convalecencia: ≥2semanas.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Contagiosidad: La mayor tasa de transmisión ocurre durante la fase catarral inicial, donde las manifestaciones clínicas son indistinguibles de un resfriado común (congestión, rinorrea, febrícula, estornudos y lagrimeo).\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, Capítulo 243, pág. 1762.",
