    "id": "semana17_ped_q245",
    "text": "En los lactantes hospitalizados por tos ferina, ¿cuál de las siguientes alteraciones laboratoriales se correlaciona directamente con una evolución clínica grave y un desenlace fatal?",
    "options": [
      "Hiperleucocitosis extrema con mediana cercana a94.000/ μ Ly trombocitosis marcada.",
      "Pancitopenia severa con anemia hemolítica microangiopática concomitante.",
      "Eosinofilia periférica persistente superior al 25 % del recuento diferencial total.",
      "Neutropenia absoluta profunda con trombocitopenia aislada refractaria.",
      "Hipouricemia marcada asociada a hiponatremia severa por secreción inadecuada de ADH."
    ],
    "correctOptionIndex": 0,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\na) [CORRECTA]: La evolución grave y la muerte en tos ferina se correlacionan directamente con un aumento rápido y extremo del recuento leucocitario (mediana del recuento pico de94.000/ μ Len casos fatales vs.18.000/ μ Len no fatales) y trombocitosis (mediana de782.000/ μ Len fatales vs.556.000/ μ Len no fatales).\r\n\r\nb) [Incorrecta]: La pancitopenia no es la respuesta hematológica de la tos ferina.\r\n\r\nc) [Incorrecta]: El texto explícito que la eosinofilia no es una manifestación de la tos ferina.\r\n\r\nd) [Incorrecta]: El incremento absoluto de neutrófilos sugiere sobreinfección bacteriana secundaria u otro diagnóstico alternativo, mientras que la neutropenia aislada no es el patrón habitual.\r\n\r\ne) [Incorrecta]: La hipouricemia no se describe como un marcador de mortalidad en estos pacientes.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Morfología celular: Los linfocitos observados en la linfocitosis absoluta son células maduras, pequeñas y normales (a diferencia de los linfocitos grandes y atípicos de las infecciones virales).\r\n- Hallazgos radiográficos de tórax: Infiltrados perihiliares o edema (ocasionalmente con aspecto en mariposa) y atelectasias variables. La presencia de consolidación parenquimatosa sugiere sobreinfección bacteriana secundaria.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Complicaciones mecánicas por accesos de tos: Hemorragias conjuntivales, petequias en la parte superior del cuerpo, neumotórax, neumomediastino y enfisema subcutáneo.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, Capítulo 243, pág. 1762.",
