    "id": "semana17_ped_q246",
    "text": "¿Cuál es el fármaco de primera línea y la duración del tratamiento recomendado para un lactante de 2 meses de edad con sospecha clínica o confirmación de tos ferina?",
    "options": [
      "Azitromicina en dosis única diaria de$10\\text{ mg/kg/día}$durante 5 días.",
      "Claritromicina fraccionada cada 12 horas por un total de 14 días.",
      "Eritromicina oral fraccionada en 4 tomas diarias durante 21 días.",
      "Trimetoprima-sulfametoxazol cada 12 horas por un lapso de 7 días.",
      "Amoxicilina con ácido clavulánico cada 8 horas por 10 días completos."
    ],
    "correctOptionIndex": 0,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\na) [CORRECTA]: La azitromicina a dosis de$10\\text{ mg/kg/día}$en una sola toma diaria durante 5 días es el agente de elección ( fármaco preferido ) en todos los grupos etarios (incluidos lactantes de 1 a 5 meses) tanto para el tratamiento de la infección como para la profilaxis posexposición.\r\n\r\nb) [Incorrecta]: La claritromicina se administra a$15\\text{ mg/kg/día}$en 2 dosis divididas durante 7 días y figura como agente alternativo.\r\n\r\nc) [Incorrecta]: La eritromicina se indica durante 14 días (no 21) y se asocia significativamente a estenosis hipertrófica del píloro en lactantes menores.\r\n\r\nd) [Incorrecta]: El TMP-SMX es una alternativa para lactantes$\\ge 2$meses, pero su pausa de administración dura 14 días (no 7).\r\n\r\ne) [Incorrecta]: Los betalactámicos no son eficaces para el tratamiento ni la erradicación nasofaríngea de Bordetella pertussis .\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Objetivo de los antibióticos: Disminuir la contagiosidad y ofrecer un potencial beneficio clínico cuando se inician precozmente.\r\n- Aislamiento: Precauciones de gotas durante la hospitalización hasta completar 5 días de tratamiento efectivo con azitromicina. La exclusión de escuelas o guarderías se mantiene por 5 días.\r\n- Contraindicación de TMP-SMX: Contraindicado en recién nacidos y lactantes menores de 2 meses por riesgo de kernicterus.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n**Tratamiento según edad (Azitromicina):**\r\n- $<6$meses:$10\\text{ mg/kg/día}$en monodosis por 5 días.\r\n- $\\ge 6$meses y niños:$10\\text{ mg/kg}$el día 1 (máx.$500\\text{ mg}$), luego$5\\text{ mg/kg/día}$(máx.$250\\text{ mg}$) del día 2 al 5.\r\n- Adultos:$500\\text{ mg}$el día 1, luego$250\\text{ mg/día}$del día 2 al 5.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, Capítulo 243, págs. 1763-1764.",
