    "id": "semana17_ped_q247",
    "text": "¿Cuál es la complicación digestiva grave asociada al uso de macrólidos (particularmente eritromicina) en recién nacidos y lactantes menores de 14 días?",
    "options": [
      "Estenosis hipertrófica del píloro de presentación infantil.",
      "Enterocolitis necrosante fulminante del recién nacido de término.",
      "Invaginación intestinal ileocecal aguda secundaria a placas de Peyer.",
      "Íleo meconial obstructivo por aumento de la viscosidad secretora.",
      "Perforación gástrica espontánea por hiperacidez inducida por el fármaco."
    ],
    "correctOptionIndex": 0,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\na) [CORRECTA]: El uso de macrólidos en lactantes pequeños, especialmente en menores de 14 días de vida y con mayor frecuencia tras la administración de eritromicina en comparación con azitromicina, se asocia significativamente al desarrollo de estenosis hipertrófica del píloro . A pesar de ello, el beneficio de la profilaxis posexposición o el tratamiento supera ampliamente este riesgo potencial.\r\n\r\nb) [Incorrecta]: La enterocolitis necrosante se relaciona principalmente con la prematuraz y la isquemia intestinal, no con el uso específico de macrólidos.\r\n\r\nc) [Incorrecta]: La invaginación intestinal no es la complicación digestiva atribuida a los macrólidos en las primeras dos semanas de vida.\r\n\r\nd) [Incorrecta]: El íleo meconial se asocia a la fibrosis química y no a toxicidad por antimicrobianos.\r\n\r\ne) [Incorrecta]: La perforación gástrica espontánea no guarda relación con la administración de azitromicina o eritromicina.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Vigilancia clínica: Ante vómitos en proyectil en un lactante tratado con macrólidos por tos ferina, debe sospecharse precozmente estenosis hipertrófica del píloro.\r\n- Advertencia cardiovascular: La FDA advierte del riesgo de arritmias cardíacas letales con azitromicina en pacientes predispuestos a prolongación del intervalo QT.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Riesgo comparativo: Eritromicina$>$Azitromicina en inducción de estenosis hipertrófica pilórica en$<14$días de vida.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, Capítulo 243, pág. 1763.",
