    "tema": "Infectología",
    "subtema": "Tratamiento Antituberculoso y Toxicidad",
    "subtema_grupo": "Enfermedades Bacterianas",
    "module": "Semana 17 - Pediatría",
    "pagina": "📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, Capítulo 261, Tabla 261.9, pág. 1853."
