    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\ne) [CORRECTA]: Leishmania (Viannia) braziliensis es la especie más frecuentemente asociada al desarrollo de leishmaniasis mucosa (espundia) en el continente americano (distribuida desde el norte de Argentina hasta Centroamérica). Se origina por diseminación metastásica hematógena desde una lesión cutánea previa hacia la mucosa nasal, orofaríngea o laríngea.\r\n\r\na) [Incorrecta]: Leishmania amazonensis produce principalmente leishmaniasis cutánea localizada y cutánea difusa en la cuenca amazónica.\r\n\r\nb) [Incorrecta]: Leishmania mexicana causa la úlcera del chiclero (afectación cutánea del pabellón auricular) en México y Centroamérica.\r\n\r\nc) yd) [Incorrectas]: Aunque pertenece al subgénero Viannia y causan leishmaniasis cutánea, L. braziliensis es el agente causal predominante y clásico de la espundia destructiva.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Frecuencia: Ocurre en menos del 5 % de los pacientes que padecieron leishmaniasis cutánea por L. braziliensis.\r\n- Evolución: Las manifestaciones mucosas pueden aparecer meses o años después de la cicatrización de la lesión cutánea primaria.\r\n- Clínica: Congestión nasal persistente, epistaxis, perforación del tabique cartilaginoso nasal y deformidad facial (\"nariz de tapir\").\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Leishmania (V.) braziliensis = Causa número 1 de Espundia (compromiso cartilaginoso nasal/palatino).\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, Capítulo 331, págs.",
