    "correctOptionIndex": 4,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\ne) [CORRECTA]: Leishmania (Leishmania) mexicana es el agente clásico de la denominada úlcera del chiclero en México y Centroamérica. Esta presentación afecta de manera característica el pabellón auricular (hélix/antihélix), mostrando un curso crónico, destructivo y de difícil cicatrización debido a la avascularidad relativa del cartílago auricular.\r\n\r\na) [Incorrecta]: L. infantum es la causante de la leishmaniasis visceral infantil.\r\n\r\nb) [Incorrecta]: L. braziliensis causa úlceras cutáneas de mayor tamaño con tendencia a extensión mucosa y diseminación linfangítica.\r\n\r\nc) [Incorrecta]: L. peruviana causa la forma cutánea denominada \"uta\" en los valles andinos occidentales.\r\n\r\nd) [Incorrecta]: L. guyanensis predomina en el norte de Sudamérica produciendo lesiones cutáneas conocidas como \"pian-bois\".\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Distribución de L. mexicana: Desde el sur de Estados Unidos (Texas) pasando por México hasta América Central.\r\n- Compromiso auricular: Destrucción y mutilación parcial del cartílago de la oreja en ausencia de tratamiento específico.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Úlcera del chiclero = Cartílago auricular + Leishmania mexicana.\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, Capítulo 331, págs.",
