    "id": "semana17_ped_q270",
    "text": "En América Latina (especialmente en la cuenca del Amazonas), ¿cuál de las siguientes especies causa la leishmaniasis cutánea difusa, caracterizada por lesiones nodulares no ulceradas de tipo lepromatoso con prueba de Montenegro negativa por anergia?",
