    "correctOptionIndex": 3,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\nd) [CORRECTA]: En América del Sur (cuenca amazónica y países limítrofes), la leishmaniasis cutánea difusa (LCD) es ocasionada principalmente por miembros del complejo mexicano, destacando Leishmania (Leishmania) amazonensis (y L. pifanoi en Venezuela). Se manifiesta con placas y nódulos diseminados no ulcerados que simulan una lepra lepromatosa, con infiltración dérmica masiva de macrófagos llenos de amastigotes y anergia celular demostrada por prueba de Montenegro negativa .\r\n\r\na) [Incorrecta]: L. braziliensis causa la forma diseminada (con pápulas y úlceras inflamatorias abiertas) y tiene intradermorreacción de Montenegro positiva.\r\n\r\nb) [Incorrecta]: L. peruviana causa lesiones cutáneas benignas y autolimitadas en los Andes sin producir la forma difusa anérgica.\r\n\r\nc) [Incorrecta]: L. infantum es el agente de la forma visceral (Kala-azar).\r\n\r\ne) [Incorrecta]: Aunque pertenece al mismo complejo, L. amazonensis es la especie sudamericana representativa de las formas difusas lepromatosas.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n**Diferencia entre Cutánea Diseminada y Cutánea Difusa:**\r\n- Diseminada (L. braziliensis): Más de 10 a cientos de úlceras/pápulas inflamatorias, prueba de Montenegro positiva .\r\n- Difusa (L. amazonensis): Máculas y nódulos no ulcerados tipo lepromatoso, prueba de Montenegro negativa (defecto inmune celular específico).\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- LCD Sudamericana = Placas no ulceradas + Anergia a Montenegro + Leishmania amazonensis .\r\n- 📖 Referencia: Nelson, Tratado de Pediatría, 22.ª edición, Capítulo 331, págs.",
