    "correctOptionIndex": 2,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\n- **Correcta:** «Ivermectina» — Para la larva migrans cutánea, el tratamiento con ivermectina (200 mcg/kg vía oral en dosis única para niños con peso > 15 kg) es considerado el fármaco de elección por algunos investigadores.\r\n- **Incorrecta:** «Metronidazol» — El metronidazol es un antiprotozoario y antibacteriano anaeróbico sin actividad contra larvas de helmintos.\r\n- **Incorrecta:** «Pamoato de pirantel» — El pamoato de pirantel se usa como alternativa en uncinariasis intestinal, no en la invasión cutánea migratoria.\r\n- **Incorrecta:** «Praziquantel» — El praziquantel es de elección para trematodos y cestodos.\r\n- **Incorrecta:** «Piperazina» — El citrato de piperazina se empleaba en obstrucción por Ascaris .\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Otras opciones terapéuticas descritas para la larva migrans cutánea: albendazol (400 mg/día VO por 3 días en > 2 años) o tiabendazol tópico.\r\n- Si no se trata, las larvas mueren espontáneamente y el síndrome se resuelve en un período de pocas semanas a varios meses.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Fármaco de elección (> 15 kg): Ivermectina 200 mcg/kg VO en dosis única.\r\n- Alternativa oral (>2 años): Albendazol 400 mg/día VO por 3 días.\r\n- Alternativa tópica: Tiabendazol tópico.\r\n- 📖 Referencia: Nelson Textbook of Pediatrics, 22.ª Edición,  , Parte XV, Capítulo 338: Anquilostomas (Necator americanus y Ancylostoma spp.) , página 2202.",
