    "correctOptionIndex": 1,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\n- **Correcta:** «Pamoato de oxantel (20 mg/kg) más 400 mg de albendazol en días consecutivos» — El texto señala textualmente que los regímenes de dosis única con albendazol, nitazoxanida o albendazol más nitazoxanida presentan tasas de curación bajas y de corta duración. Por el contrario, la terapia combinada con pamoato de oxantel (20 mg/kg) más 400 mg de albendazol en días consecutivos puede presentar la tasa de curación más alta.\r\n- **Incorrecta:** «Tiabendazol tópico más permetrina al 5% en crema» — El tiabendazol tópico se emplea en larva migrans cutánea y la permetrina en escabiosis.\r\n- **Incorrecta:** «Metronidazol (30 mg/kg) más citrato de piperazina en dosis única» — El metronidazol no se usa para helmintos intestinales y la piperazina se empleaba para Ascaris .\r\n- **Incorrecta:** «Ivermectina (200 mcg/kg) más sulfato ferroso por 30 días» — La ivermectina para Trichuris se prescribe a 600 mcg/kg/día por 3 días como alternativa, no a 200 mcg/kg con hierro como régimen de máxima erradicación parasitaria.\r\n- **Incorrecta:** «Pamoato de pirantel (11 mg/kg) más mebendazol 500 mg en toma simultánea» — El pamoato de oxantel es el análogo del pirantel específico para Trichuris ; el pirantel convencional no forma este esquema de alta tasa de cura.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Fármaco de elección estándar: Albendazol 400 mg VO diario por 3 días (curación 70-90%).\r\n\r\n**Alternativas efectivas de 3 días:**\r\n- Mebendazol 100 mg VO dos veces al día por 3 días.\r\n- Ivermectina 600 mcg/kg VO al día por 3 días.\r\n- Régimen con mayor tasa de éxito descrito: Pamoato de oxantel (20 mg/kg) + albendazol 400 mg en días consecutivos.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Fracaso de dosis única: Albendazol o nitazoxanida en monodosis tienen bajas tasas de curación.\r\n- Esquema combinado superior: Pamoato de oxantel (20 mg/kg) + Albendazol (400 mg) en días consecutivos.\r\n- Pautas de 3 días requeridas: Albendazol 400 mg/dx 3 d, Mebendazol 100 mg c/12h x 3 do Ivermectina 600 mcg/kg/dx 3 d.\r\n- 📖 Referencia: Nelson Textbook of Pediatrics, 22.ª Edición,  , Parte XV, Capítulo 339: Trichuriasis (Trichuris trichiura) , página 2203.",
