    "correctOptionIndex": 1,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\n- **Correcta:** «Prolapso rectal; Albendazol» — La complicación clásica de la infección grave por Trichuris trichiura es el prolapso rectal y el fármaco de elección es el albendazol (400 mg VO al día por 3 días).\r\n- **Incorrecta:** «Vólvulo gástrico; tiabendazol» — El vólvulo gástrico no es complicación de helmintos ni el tiabendazol es la primera línea.\r\n- **Incorrecta:** «Obstrucción biliar; Prazicuantel» — La obstrucción biliar es típica de Ascaris lumbricoides y el praziquantel se usa en cestodos/trematodos.\r\n- **Incorrecta:** «Enteritis eosinofílica; metronidazol» — La enteritis eosinofílica corresponde a Ancylostoma caninum .\r\n- **Incorrecta:** «Perforación cecal; ivermectina» — La perforación cecal no es la manifestación habitual descrita y la ivermectina es un tratamiento alternativo, no el de primera elección.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Tríada/Clínica grave: Disentería crónica, anemia ferropénica y prolapso rectal.\r\n- Diagnóstico: Huevos característicos en forma de barril en heces.\r\n- Tratamiento estándar: Albendazol 400 mg vía oral al día durante 3 días consecutivos.\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Complicación distintiva: Prolapso rectal en niños pequeños con alta carga parasitaria.\r\n- Tratamiento de elección: Albendazol (400 mg/día por 3 días).\r\n- Alternativas de 3 días: Mebendazol (100 mg c/12h x 3 días) o Ivermectina (600 mcg/kg/día x 3 días).\r\n- 📖 Referencia: Nelson Textbook of Pediatrics, 22.ª Edición,  , Parte XV, Capítulo 339: Trichuriasis (Trichuris trichiura) , página 2203.",
