    "correctOptionIndex": 4,
    "explanation": "🧠 ANÁLISIS DE LA PREGUNTA\r\n\r\n- **Incorrecta:** «Toxocara canis →Hidrocefalia obstructiva aguda secundaria a quistes intraventriculares calcificados gigantes» — La hidrocefalia obstructiva secundaria a quistes intraventriculares es una complicación característica de la neurocisticercosis ( Taenia solium ) , la cual representa hasta el 20% de los casos. Toxocara canis produce larva migrans visceral (hepatomegalia, asma, eosinofilia) o larva migrans ocular (granulomas retinianos), y no hay géneros quistes vesiculares intraventriculares obstructivos.\r\n- **Correcta:** «Ascaris lumbricoides →Obstrucción mecánica intestinal aguda en niños con alta carga y litiasis biliar secundaria a vermes muertos» — Los áscaris producen masas oclusivas intraluminales y pueden actuar como núcleo litogénico en conductos biliares.\r\n- **Correcta:** «Ancylostoma duodenale →Forma infantil grave de anquilostomiasis caracterizada por diarrea, melena, fallo de medro y anemia profunda» — La anquilostomiasis infantil por A. duodenale es una causa grave y letal de melena y anemia severa en lactantes.\r\n- **Correcta:** «Trichuris trichiura →Disentería crónica, acropaquia , desnutrición proteico-calórica y prolapso rectal» — La infección masiva por tricocéfalos cursa clásicamente con síndrome disentérico crónico, desnutrición, acropaquia y prolapso rectal.\r\n- **Correcta:** «Strongyloides stercoralis →Síndrome de hiperinfección con diseminación sistémica y bacteriemia por flora entérica en pacientes inmunodeprimidos» — En inmunodeprimidos (alteración de la inmunidad celular mediada por linfocitos por uso prolongado de corticoides), la autoinfección acelerada causa hiperinfección y sepsis por arrastre de bacterias intestinales.\r\n\r\n🔑 CONCEPTOS CLAVE\r\n\r\n- Obstrucción mecánica intraluminal: Exclusiva de Ascaris lumbricoides .\r\n- Sangrado con melena / anemia infantil severa: Ancylostoma duodenale .\r\n- Prolapso rectal + disentería: Trichuris trichiura .\r\n- Sepsis/bacteriemia por translocación larvaria: Strongyloides stercoralis .\r\n- Crisis convulsivas / Hidrocefalia intraventricular: Taenia solium .\r\n\r\n⚡ REPASO ACTIVO\r\n\r\n- Ascaris: Suboclusión / Oclusión por ovillo de gusanos.\r\n- Tricocefalo: Prolapso rectal.\r\n- Uncinarias: Anemia ferropénica severa / Melena / Clorosis.\r\n- Estrongiloides: Hiperinfección en inmunosuprimidos + Larva currens.\r\n- Toxocara: Larva migrans visceral (hepatomegalia + sibilancias) y ocular (leucocoria/granuloma retiniano).\r\n- 📖 Referencia: Nelson Textbook of Pediatrics, 22.ª Edición, , Parte XV, Capítulos 337 (p. 2199), 338 (p. 2201), 339 (p. 2203), 341 (p. 2205) y 349 (p. 2218).",
